//! phpMyAdmin at `http://localhost/phpmyadmin`: downloaded from phpmyadmin.net (checksum
//! verified), configured for NexDB's MySQL, and served by Apache through an alias.

use crate::catalog::Download;
use crate::configure;
use crate::installer::{self, Progress};
use serde::Serialize;
use std::fs;
use std::path::{Path, PathBuf};

pub fn dir(root: &Path) -> PathBuf {
    root.join("tools").join("phpmyadmin")
}

pub fn installed(root: &Path) -> bool {
    dir(root).join("index.php").is_file()
}

/// The version recorded in phpMyAdmin's own `libraries/classes/Version.php`, if readable.
pub fn version(root: &Path) -> Option<String> {
    let text = fs::read_to_string(dir(root).join("libraries").join("classes").join("Version.php")).ok()?;
    let start = text.find("VERSION = '")? + "VERSION = '".len();
    let end = text[start..].find('\'')?;
    Some(text[start..start + end].to_string())
}

#[derive(Serialize)]
pub struct Status {
    pub installed: bool,
    pub version: Option<String>,
    pub url: String,
    /// phpMyAdmin is served by Apache, so it needs the web server in this install.
    pub web_server: bool,
}

pub fn status(root: &Path, apache_port: Option<u16>) -> Status {
    let suffix = match apache_port {
        Some(80) | None => String::new(),
        Some(p) => format!(":{p}"),
    };
    Status {
        installed: installed(root),
        version: version(root),
        url: format!("http://localhost{suffix}/phpmyadmin/"),
        web_server: apache_port.is_some(),
    }
}

fn php_string(path: &Path) -> String {
    configure::conf_path(path).replace('\\', "/").replace('\'', "\\'")
}

/// `config.inc.php`: one server, NexDB's MySQL, cookie login, no update nag.
pub fn config_php(secret: &str, mysql_port: u16, temp_dir: &Path) -> String {
    format!(
        "<?php\n// Generated by NexDB. Changes here are overwritten.\n\
         $cfg['blowfish_secret'] = '{secret}';\n\
         $i = 0;\n$i++;\n\
         $cfg['Servers'][$i]['auth_type'] = 'cookie';\n\
         $cfg['Servers'][$i]['host'] = '127.0.0.1';\n\
         $cfg['Servers'][$i]['port'] = '{mysql_port}';\n\
         $cfg['Servers'][$i]['compress'] = false;\n\
         $cfg['Servers'][$i]['AllowNoPassword'] = true;\n\
         $cfg['TempDir'] = '{}';\n\
         $cfg['VersionCheck'] = false;\n\
         $cfg['PmaNoRelation_DisableWarning'] = true;\n\
         $cfg['ThemeDefault'] = 'nexdb';\n",
        php_string(temp_dir)
    )
}

/// The secret already in `config.inc.php`, so logins survive a rewrite.
fn existing_secret(config: &Path) -> Option<String> {
    let text = fs::read_to_string(config).ok()?;
    let start = text.find("blowfish_secret'] = '")? + "blowfish_secret'] = '".len();
    let end = text[start..].find('\'')?;
    let secret = &text[start..start + end];
    (secret.len() == 32).then(|| secret.to_string())
}

fn new_secret() -> Result<String, String> {
    let mut bytes = [0u8; 16];
    getrandom::fill(&mut bytes).map_err(|e| format!("Couldn't create a secret: {e}"))?;
    Ok(bytes.iter().map(|b| format!("{b:02x}")).collect())
}

pub fn apache_alias(root: &Path) -> String {
    let d = configure::conf_path(&dir(root));
    format!(
        "# Generated by NexDB. phpMyAdmin is only reachable from this PC.\n\
         Alias /phpmyadmin \"{d}\"\n\
         <Directory \"{d}\">\n    Options FollowSymLinks\n    DirectoryIndex index.php\n    AllowOverride None\n    Require local\n\
         # Always re-check stylesheets and scripts, so theme updates show up straight away.\n\
         <IfModule headers_module>\n\
             <FilesMatch \"\\.(css|js)$\">\n\
                 Header set Cache-Control \"no-cache\"\n\
             </FilesMatch>\n\
         </IfModule>\n\
         # The script lives outside the document root, so build its real path from the alias.\n\
         ProxyFCGISetEnvIf \"reqenv('SCRIPT_NAME') =~ m#^/phpmyadmin(/.*)$#\" SCRIPT_FILENAME \"{d}$1\"\n\
         </Directory>\n"
    )
}

const THEME_CSS: &str = include_str!("../assets/nexdb-theme.css");
/// Bump when the theme changes so existing installs get the new version.
const THEME_VERSION: &str = "9";

fn copy_dir(from: &Path, to: &Path) -> std::io::Result<()> {
    fs::create_dir_all(to)?;
    for entry in fs::read_dir(from)? {
        let entry = entry?;
        let target = to.join(entry.file_name());
        if entry.file_type()?.is_dir() {
            copy_dir(&entry.path(), &target)?;
        } else {
            fs::copy(entry.path(), target)?;
        }
    }
    Ok(())
}

/// Builds the `nexdb` theme: a copy of the default theme with NexDB's stylesheet added at the end.
pub fn install_theme(root: &Path) -> Result<(), String> {
    let themes = dir(root).join("themes");
    let theme = themes.join("nexdb");
    let marker = theme.join(".nexdb-theme");
    if fs::read_to_string(&marker).ok().as_deref() == Some(THEME_VERSION) {
        return Ok(());
    }
    let base = themes.join("pmahomme");
    if !base.is_dir() {
        return Err("phpMyAdmin's default theme is missing, so the NexDB theme can't be built.".into());
    }
    if theme.exists() {
        fs::remove_dir_all(&theme).map_err(|e| e.to_string())?;
    }
    copy_dir(&base, &theme).map_err(|e| format!("Couldn't build the NexDB theme: {e}"))?;
    for name in ["theme.css", "theme.rtl.css"] {
        let css = theme.join("css").join(name);
        let mut text = fs::read_to_string(&css).map_err(|e| e.to_string())?;
        // The source map points at the original file; it no longer matches.
        text = text.lines().filter(|l| !l.starts_with("/*# sourceMappingURL")).collect::<Vec<_>>().join("\n");
        text.push('\n');
        text.push_str(THEME_CSS);
        fs::write(&css, text).map_err(|e| e.to_string())?;
    }
    fs::write(
        theme.join("theme.json"),
        "{\n    \"name\": \"NexDB\",\n    \"version\": \"5.0\",\n    \"description\": \"NexDB light and dark theme\",\n    \"author\": \"NexDB\",\n    \"url\": \"\",\n    \"supports\": [\"5.0\", \"5.1\", \"5.2\"]\n}\n",
    )
    .map_err(|e| e.to_string())?;
    fs::write(&marker, THEME_VERSION).map_err(|e| e.to_string())
}

/// Writes phpMyAdmin's config and Apache alias, or removes the alias when it isn't installed.
pub fn write_config(root: &Path, mysql_port: Option<u16>) -> Result<(), String> {
    let alias = root.join("etc").join("apache").join("extra").join("phpmyadmin.conf");
    if !installed(root) {
        let _ = fs::remove_file(&alias);
        return Ok(());
    }
    install_theme(root)?;
    let temp = root.join("tmp").join("phpmyadmin");
    fs::create_dir_all(&temp).map_err(|e| format!("Couldn't create {}: {e}", temp.display()))?;
    let config = dir(root).join("config.inc.php");
    let secret = match existing_secret(&config) {
        Some(s) => s,
        None => new_secret()?,
    };
    configure::write_file(&config, &config_php(&secret, mysql_port.unwrap_or(3306), &temp))?;
    configure::write_file(&alias, &apache_alias(root))
}

pub async fn install(
    download: &Download,
    root: &Path,
    mysql_port: Option<u16>,
    emit: &impl Fn(Progress),
) -> Result<(), String> {
    installer::install_archive(download, root, &dir(root), "get-phpmyadmin", emit).await?;
    write_config(root, mysql_port)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn config_is_cookie_login_on_the_chosen_port() {
        let c = config_php(&"a".repeat(32), 3307, Path::new(r"C:\NexDB\tmp\phpmyadmin"));
        assert!(c.contains("['port'] = '3307'"));
        assert!(c.contains("['auth_type'] = 'cookie'"));
        assert!(c.contains("C:/NexDB/tmp/phpmyadmin"), "{c}");
        assert!(c.contains("blowfish_secret'] = 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'"));
    }

    #[test]
    fn secret_survives_rewrites_and_is_random() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        fs::create_dir_all(super::dir(root)).unwrap();
        fs::write(super::dir(root).join("index.php"), "<?php").unwrap();
        let css = super::dir(root).join("themes").join("pmahomme").join("css");
        fs::create_dir_all(&css).unwrap();
        for name in ["theme.css", "theme.rtl.css"] {
            fs::write(css.join(name), "body{margin:0}\n/*# sourceMappingURL=theme.css.map */").unwrap();
        }
        write_config(root, Some(3306)).unwrap();
        let built = fs::read_to_string(super::dir(root).join("themes/nexdb/css/theme.css")).unwrap();
        assert!(built.starts_with("body{margin:0}") && built.contains("NexDB theme for phpMyAdmin"));
        assert!(!built.contains("sourceMappingURL"));
        assert!(fs::read_to_string(super::dir(root).join("config.inc.php")).unwrap().contains("'nexdb'"));
        let config = super::dir(root).join("config.inc.php");
        let first = existing_secret(&config).unwrap();
        write_config(root, Some(3310)).unwrap();
        assert_eq!(existing_secret(&config).unwrap(), first);
        assert!(fs::read_to_string(&config).unwrap().contains("'3310'"));
        assert_ne!(new_secret().unwrap(), new_secret().unwrap());
        assert!(root.join("etc/apache/extra/phpmyadmin.conf").is_file());
        // Without the app the alias goes away.
        fs::remove_file(super::dir(root).join("index.php")).unwrap();
        write_config(root, Some(3306)).unwrap();
        assert!(!root.join("etc/apache/extra/phpmyadmin.conf").exists());
    }

    #[test]
    fn status_builds_the_address() {
        let root = Path::new(r"C:\does\not\exist");
        assert_eq!(status(root, Some(80)).url, "http://localhost/phpmyadmin/");
        assert_eq!(status(root, Some(8080)).url, "http://localhost:8080/phpmyadmin/");
        assert!(!status(root, None).web_server);
    }

    /// Downloads the real phpMyAdmin, serves it through NexDB's Apache and PHP on spare ports, and
    /// logs in to a throwaway NexDB MySQL: `cargo test real_phpmyadmin -- --ignored --nocapture`
    #[test]
    #[ignore]
    fn real_phpmyadmin() {
        use crate::supervisor::{ServiceSpec, StopMethod, Supervisor, specs_for};
        use std::io::{Read, Write};
        use std::net::TcpStream;

        let base = crate::settings::load(Path::new(r"C:\NexDB")).expect("NexDB must be installed in C:/NexDB");
        let dir_root = tempfile::tempdir().unwrap();
        let root = dir_root.path();
        let www = root.join("www");
        fs::create_dir_all(&www).unwrap();
        fs::create_dir_all(root.join("tmp").join("downloads")).unwrap();

        // A throwaway MySQL on a spare port.
        let mysql_dir = PathBuf::from(&base.components.iter().find(|c| c.id == "mysql").unwrap().path);
        let (data, logs) = (root.join("data"), root.join("logs"));
        fs::create_dir_all(&logs).unwrap();
        let ini = root.join("my.ini");
        configure::write_file(&ini, &configure::mysql_ini(&configure::MysqlConf { base_dir: &mysql_dir, data_dir: &data, port: 3396, logs_dir: &logs })).unwrap();
        configure::setup_mysql(&mysql_dir, &ini, &data, 3396, Some("pma-pass")).unwrap();

        let catalog = crate::catalog::bundled();
        let steps = std::sync::Mutex::new(0u32);
        tauri::async_runtime::block_on(install(&catalog.tools.phpmyadmin.download, root, Some(3396), &|_| *steps.lock().unwrap() += 1)).unwrap();
        println!("progress events: {}", steps.lock().unwrap());
        assert!(installed(root));
        println!("phpMyAdmin {}", version(root).unwrap_or_default());

        let mut settings = base.clone();
        settings.www_dir = www.display().to_string();
        settings.apache_port = Some(8096);
        settings.php_fastcgi_port = 9196;
        settings.nginx_port = None;
        settings.mysql = Some(crate::settings::MysqlSettings { port: 3396, existing: false, data_dir: Some(data.display().to_string()) });
        crate::installer::refresh_configs(root, &settings).unwrap();
        assert!(root.join("etc/apache/extra/phpmyadmin.conf").is_file());

        let mut specs = specs_for(root, &settings);
        specs.retain(|s| s.id != "mysql");
        specs.push(ServiceSpec {
            id: "mysql".into(), name: "MySQL".into(), version: None, exe: mysql_dir.join("bin").join("mysqld.exe"),
            args: vec![format!("--defaults-file={}", ini.display()), "--console".into()],
            cwd: mysql_dir.clone(), port: 3396, managed: true, stop: StopMethod::MysqlEvent, log: logs.join("mysql_error.log"),
        });
        let sup = Supervisor::new(specs);
        for id in ["mysql", "php", "apache"] {
            sup.start(id).unwrap();
        }

        // `NEXDB_DEMO=<file>` keeps the stack up (http://localhost:8096/phpmyadmin/, root / pma-pass)
        // until that file exists, so the theme can be looked at in a browser.
        if let Some(stop) = std::env::var_os("NEXDB_DEMO") {
            let sql = "CREATE DATABASE shop; CREATE TABLE shop.customers (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(60) NOT NULL, email VARCHAR(120), joined DATE); INSERT INTO shop.customers (name, email, joined) VALUES ('Ada Lovelace','ada@example.com','2026-01-04'),('Linus Torvalds','linus@example.com','2026-02-11'),('Grace Hopper','grace@example.com','2026-03-02');";
            let client = mysql_dir.join("bin").join("mysql.exe");
            configure::run_with_stdin(&client, &["--protocol=TCP", "-h", "127.0.0.1", "-P", "3396", "-u", "root", "-ppma-pass"], sql, std::time::Duration::from_secs(30)).unwrap();
            println!("DEMO READY");
            while !Path::new(&stop).exists() {
                std::thread::sleep(std::time::Duration::from_secs(1));
            }
            sup.stop_all();
            return;
        }
        let request = |method: &str, path: &str, cookie: &str, body: &str| {
            let mut s = TcpStream::connect(("127.0.0.1", 8096)).unwrap();
            let req = format!(
                "{method} {path} HTTP/1.0\r\nHost: localhost:8096\r\nCookie: {cookie}\r\nContent-Type: application/x-www-form-urlencoded\r\nContent-Length: {}\r\n\r\n{body}",
                body.len()
            );
            s.write_all(req.as_bytes()).unwrap();
            let mut out = String::new();
            s.read_to_string(&mut out).unwrap();
            out
        };
        let login = request("GET", "/phpmyadmin/index.php", "", "");
        println!("{}", login.lines().next().unwrap_or_default());
        assert!(login.contains("200 OK"), "{}", &login[..login.len().min(800)]);
        assert!(login.contains("pma_username"), "login form expected: {}", &login[..login.len().min(1200)]);
        let warnings = ["Deprecated:", "Warning:", "Fatal error", "Parse error"];
        for w in warnings {
            assert!(!login.contains(w), "PHP printed {w} on the login page:\n{}", &login[..login.len().min(1500)]);
        }
        // Cookie-based login: phpMyAdmin issues a token and a session cookie first.
        let cookie = login
            .lines()
            .filter_map(|l| l.strip_prefix("Set-Cookie: "))
            .filter_map(|c| c.split(';').next())
            .collect::<Vec<_>>()
            .join("; ");
        let token = login.split("name=\"token\" value=\"").nth(1).and_then(|r| r.split('"').next()).unwrap_or_default().to_string();
        assert!(!token.is_empty(), "token missing");
        let body = format!("pma_username=root&pma_password=pma-pass&server=1&route=%2F&token={token}");
        let post = request("POST", "/phpmyadmin/index.php?route=/", &cookie, &body);
        println!("login POST -> {}", post.lines().next().unwrap_or_default());
        println!("POST headers:
{}", post.split("

").next().unwrap_or_default());
        // A cookie jar: later Set-Cookie headers replace earlier ones with the same name.
        let mut jar: std::collections::BTreeMap<String, String> = std::collections::BTreeMap::new();
        for line in format!("{login}\r\n{post}").lines().filter_map(|l| l.strip_prefix("Set-Cookie: ")) {
            if let Some((name, value)) = line.split(';').next().and_then(|c| c.split_once('=')) {
                jar.insert(name.to_string(), value.to_string());
            }
        }
        let after_cookie = jar.iter().map(|(k, v)| format!("{k}={v}")).collect::<Vec<_>>().join("; ");
        let home = request("GET", "/phpmyadmin/index.php?route=/", &after_cookie, "");
        println!("home -> {}", home.lines().next().unwrap_or_default());
        println!("home has: login-form={} db-server={} 9.7={} err={}", home.contains("pma_username"), home.contains("Database server"), home.contains("9.7"), home.split("alert-danger").nth(1).unwrap_or("-").chars().take(200).collect::<String>());
        assert!(home.contains("200 OK"), "{}", &home[..home.len().min(1500)]);
        assert!(home.contains("Database server") && home.contains("9.7"), "logged-in home expected: {}", &home[..home.len().min(2500)]);
        for w in warnings {
            assert!(!home.contains(w), "PHP printed {w} after login:\n{}", &home[..home.len().min(2500)]);
        }
        let wrong = request("POST", "/phpmyadmin/index.php?route=/", &cookie, &body.replace("pma-pass", "nope"));
        // A wrong password redirects to the login page, which then shows MySQL's refusal.
        let mut jar2 = std::collections::BTreeMap::new();
        for line in format!("{login}\r\n{wrong}").lines().filter_map(|l| l.strip_prefix("Set-Cookie: ")) {
            if let Some((name, value)) = line.split(';').next().and_then(|c| c.split_once('=')) {
                jar2.insert(name.to_string(), value.to_string());
            }
        }
        let jar2 = jar2.iter().map(|(k, v)| format!("{k}={v}")).collect::<Vec<_>>().join("; ");
        let retry = request("GET", "/phpmyadmin/index.php?route=/", &jar2, "");
        assert!(!retry.contains("Database server") && !wrong.contains("Database server"), "a wrong password must not log in");
        assert!(retry.contains("pma_username") || wrong.contains("pma_username") || wrong.contains("Location:"), "wrong password goes back to the login form");
        sup.stop_all();
    }
}
